// Coordination math: reliability multiplies, context adds (plain JS)
function teamReliability(agentAccuracies) {
  return agentAccuracies.reduce((p, a) => p * a, 1);
}
function contextBill(perAgentTokens, agents, sharedTokens) {
  return sharedTokens + perAgentTokens * agents; // linear per added agent
}
console.log(teamReliability([0.95, 0.95, 0.95])); // 0.857: three 95s ≈ 86%
// Lesson: each handoff must EARN its error share via specialization gains.

