function teamReliability(accs) { return accs.reduce((p, a) => p * a, 1); }
function contextBill(perAgent, n, shared) { return shared + perAgent * n; }
const solo = { acc: 0.9, ctx: 2000 };
const team = { accs: [0.97, 0.97, 0.97], perAgent: 1200, n: 3, shared: 800 };
console.log('solo acc=' + solo.acc + ' ctx=' + solo.ctx);
console.log('team acc=' + Math.round(teamReliability(team.accs) * 1000) / 1000);
console.log('team ctx=' + contextBill(team.perAgent, team.n, team.shared));
console.log('verdict=' + (teamReliability(team.accs) > solo.acc ? 'team wins' : 'solo wins'));

